function requests(){const mine=state.role==='agent';const items=requestSamples.filter(r=>!mine||r.agent==='Maria Laurent');return pageHead(mine?'My requests':'Agent requests',mine?'More stock, new ideas and corrections. All in one place.':'Review partner requests before stock or prices change.',mine?btn('New request','plus','data-request="Restock"','primary'):badge('3 awaiting review','orange'))+`<div class="metrics request-metrics">${metric('Awaiting approval',mine?'2':'3','clock-3','orange','Admin O reviews each request')}${metric('Approved','1','circle-check','green','Ready for the next step')}${metric('Your workflow','Request → review','send','blue','Stock changes after fulfillment')}</div>${mine?agentQuickActions():''}<section class="panel">${panelHead(mine?'My request history':'Approval inbox','Illustrative requests · no messages are sent')}${table(mine?['Request / date','Type','Product','Quantity','Status','']:['Request / date','Agent','Type','Product','Quantity','Status',''],items.map(r=>row([`${r.id}<small style="display:block">${r.date} 2026</small>`,...(!mine?[r.agent]:[]),r.type,r.product,`${r.qty} vials`,badge(r.status,r.status==='Pending'?'orange':'green'),btn(mine?'View':'Review','arrow-up-right',`data-review-request="${r.id}"`,'small')])) )}</section>`}
