document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b)return;if(b.dataset.previewRole){switchPreviewRole(b.dataset.previewRole);return}if(b.dataset.page)go(b.dataset.page);if(b.dataset.theme){state.theme=b.dataset.theme;localStorage.setItem('ps-theme',state.theme);document.documentElement.dataset.theme=state.theme;$$('[data-theme]').filter(n=>n.tagName==='BUTTON').forEach(n=>{n.classList.toggle('active',n.dataset.theme===state.theme);n.setAttribute('aria-pressed',String(n.dataset.theme===state.theme))})}if(b.dataset.action==='collapse'){state.collapsed=!state.collapsed;document.body.classList.toggle('collapsed',state.collapsed);b.setAttribute('aria-expanded',String(!state.collapsed));b.setAttribute('aria-label',state.collapsed?'Expand navigation':'Collapse navigation');b.title=state.collapsed?'Expand navigation':'Collapse navigation'}if(b.dataset.action==='menu')toggleMobileNavigation();if(b.dataset.agent!==undefined){state.agent=+b.dataset.agent;go('agent')}if(b.dataset.agentIndex!==undefined)state.agent=+b.dataset.agentIndex;if(b.dataset.modal)modal(b.dataset.modal);if(b.dataset.request)requestModal(b.dataset.request);if(b.dataset.reviewRequest)reviewRequest(b.dataset.reviewRequest);if(b.hasAttribute('data-close'))closeModal();if(b.dataset.sell!==undefined)saleModal(+b.dataset.sell);if(b.dataset.product!==undefined)productModal(+b.dataset.product);if(b.dataset.demo)demoAction(b.dataset.demo);if(b.dataset.info)openModal(b.dataset.info,`<p class="muted" style="font-size:13px;line-height:1.8">${b.dataset.info==='Matched comparison'?'Calendar weeks compare the same elapsed weekdays; month and year ranges compare corresponding calendar dates. Rolling and custom ranges compare the immediately preceding equal-length period. Both endpoints stop at the same sample time when today is included. Complete calendar months may have different day counts; the exact compared dates are shown. Demo activity only.':explanations[b.dataset.info]||'This figure is shown with sample data for design review.'}</p>`);if(b.dataset.stockfilter){state.stockFilter=b.dataset.stockfilter;$$('[data-stockfilter]').forEach(n=>n.classList.toggle('active',n===b));applyStockFilter()}if(b.dataset.listfilter){$$('[data-listfilter]').forEach(n=>n.classList.toggle('active',n===b));$$('[data-model]').forEach(n=>n.hidden=b.dataset.listfilter!=='all'&&n.dataset.model!==b.dataset.listfilter)}if(b.dataset.qty){$('#sale-qty').value=Math.max(1,+$('#sale-qty').value+ +b.dataset.qty);updateSale()}if(b.hasAttribute('data-toggle')){b.classList.toggle('on');b.setAttribute('aria-checked',b.classList.contains('on'))}if(b.dataset.report)financeReport();if(b.dataset.loginRole){loginRole=b.dataset.loginRole;$$('[data-login-role]').forEach(n=>n.classList.toggle('active',n===b))}if(b.hasAttribute('data-enter-demo')){state.role=loginRole;const roleUrl=new URL(location.href);roleUrl.searchParams.set('view',state.role);history.replaceState(null,'',roleUrl);go(state.role==='admin'?'dashboard':'agent')}if(b.dataset.valueTab){$$('[data-value-tab]').forEach(n=>n.classList.toggle('active',n===b));$('#value-label').textContent=b.dataset.valueTab==='cost'?'Remaining inventory cost':'Remaining sales potential';$('#value-amount').textContent=euro(b.dataset.valueTab==='cost'?products.reduce((s,p)=>s+p.qty*p.cost,0):5455,2)}});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-search')){state.search=e.target.value.toLowerCase();if(state.page==='agents')$$('.agent-card[data-searchable]').forEach(n=>n.hidden=!n.dataset.searchable.includes(state.search));else applyStockFilter()}if(e.target.id.startsWith('sale-'))updateSale()});
